    "id": "goddess-of-victory-nikke",
    "title": "Goddess of Victory: NIKKE",
    "section": "games",
    "type": "Play Log",
    "status": "Draft",
    "started": "2026-10-29",
    "updated": "2026-10-29",
    "writtenAt": "",
    "writtenOrder": 0,
    "summary": "Waifu collector?? Gacha?? Yes please.",
    "banner": "public/media/records/goddess-of-victory-nikke/nikke-key-art.jpg",
    "dashboardImage": "",
    "headerImage": "",
    "iconImage": "",
    "externalUrl": "",
