    "id": "steam-39210",
    "title": "FINAL FANTASY XIV Online",
    "section": "games",
    "type": "Play Log",
    "status": "Playing",
    "started": "2026-10-21",
    "updated": "2026-10-21",
    "writtenAt": "",
    "writtenOrder": 0,
    "summary": "My adventures as a WoL!",
    "banner": "https://shared.fastly.steamstatic.com/store_item_assets/steam/apps/39210/library_600x900.jpg",
    "bannerZoom": 130,
    "dashboardImage": "",
    "headerImage": "",
    "iconImage": "",
    "externalUrl": "",
